def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.2))

    prev_bids = []
    rich_aggressive = 0
    needy_opponents = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 110:
                rich_aggressive += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            needy_opponents += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if supply >= 24:
        scarcity = 0
    elif supply >= 21:
        scarcity = 1
    elif supply >= 18:
        scarcity = 2
    else:
        scarcity = 3

    if hp <= 2 or no_water_days >= 2:
        emergency_bid = max(95.0, highest_prev + 3.0)
        if scarcity >= 2:
            emergency_bid = max(emergency_bid, 125.0)
        return float(min(budget, emergency_bid))

    if hp <= 4 or no_water_days >= 1:
        if scarcity == 3:
            return float(min(budget, max(118.0, highest_prev + 2.0)))
        if scarcity == 2:
            return float(min(budget, max(92.0, avg_prev * 0.8 + 8.0)))
        return float(min(budget, 62.0))

    if rich_aggressive >= 2:
        if scarcity <= 1:
            return float(min(budget, 1.0))
        if scarcity == 2:
            return float(min(budget, 12.0))
        return float(min(budget, 38.0))

    if highest_prev >= 100:
        if scarcity <= 1:
            return float(min(budget, 2.0))
        if scarcity == 2:
            return float(min(budget, 18.0))
        return float(min(budget, 45.0))

    if needy_opponents >= 2 and scarcity >= 2:
        return float(min(budget, max(55.0, highest_prev + 2.0)))

    base_by_scarcity = [3.0, 8.0, 18.0, 34.0]
    bid = base_by_scarcity[int(scarcity)]

    if day >= 8 and hp >= 6:
        bid *= 0.7

    if budget < 80:
        bid *= 0.8

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Alive opponents
    alive_ids = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_ids.append(oid)

    if not alive_ids:
        # If alone, bid just enough to keep ourselves safe.
        target = DAILY_SALARY * 0.4
        return float(min(budget, target))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for oid in alive_ids:
        prev = opponents_status[oid].get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    # Also consider who seemed most aggressive yesterday
    # (use their max bid as a proxy if available)
    aggressive_prev = 0.0
    for oid in alive_ids:
        prev = opponents_status[oid].get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                bb = float(b)
            except Exception:
                continue
            # If they bid near the top, treat them as aggressive
            if bb >= 0.85 * highest_prev and highest_prev > 0:
                aggressive_prev = max(aggressive_prev, bb)

    # Supply pressure: when supply is higher, more water can be allocated; bidding can be slightly lower.
    # When supply is low, we must secure our share.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.0
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Our urgency: if low hp or already on no-water streak, bid more.
    urgency = 0.0
    if hp <= 2.0:
        urgency += 1.0
    if no_water_days >= 1:
        urgency += 0.6
    if no_water_days >= 2:
        urgency += 0.8

    # Baseline aggressiveness based on yesterday's top bids.
    # If others went very high, we must match/beat; otherwise, bid around a fraction of the top.
    if highest_prev > 0:
        if highest_prev >= 0.85 * DAILY_SALARY:
            # High contest: either we secure now or risk cascading no-water days.
            base = DAILY_SALARY * (0.35 if hp > 3.0 else 0.95)
            # Tighten to just above their aggression when supply is low.
            if supply_ratio < 0.5:
                base = max(base, aggressive_prev * 1.02)
        else:
            # Moderate contest: bid somewhat above their top to win when needed.
            base = max(DAILY_SALARY * 0.5, highest_prev + 1.5)
            if supply_ratio > 0.6:
                base *= 0.9
    else:
        base = DAILY_SALARY * (0.55 if hp > 3.0 else 0.75)

    # Adjust for urgency and supply.
    # When supply is low, increase bid; when supply is high, decrease slightly.
    bid = base * (1.0 + 0.25 * urgency) * (1.0 + (0.5 - supply_ratio) * 0.25)

    # Hard caps/floors to avoid overspending.
    # Never bid more than our budget; also avoid bidding too low when urgent.
    min_bid = 0.0
    if urgency >= 1.0:
        min_bid = DAILY_SALARY * 0.75
    elif urgency >= 0.6:
        min_bid = DAILY_SALARY * 0.55
    else:
        min_bid = DAILY_SALARY * 0.4

    bid = max(min_bid, bid)
    bid = min(budget, bid)

    # If budget is extremely low, bid what we can.
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimum to get water and save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Get yesterday's bids for all alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev_bid = 0
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)

    # Determine base bid strategy
    # Default bid: moderately aggressive
    base_bid = DAILY_SALARY * 0.8 # 120

    # Adjust based on my HP and no_water_days
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        # Critical state, must get water. Bid very aggressively.
        base_bid = DAILY_SALARY * 0.95 # 142.5
        if day_context['day'] >= EPISODE_DAYS - 2: # Last couple of days, go all in if critical
            base_bid = DAILY_SALARY + 5 # 155
    elif my_status['hp'] >= 8 and len(alive_opponents) > 0:
        # Healthy, can afford to be less aggressive if competition is high
        if max_prev_bid > DAILY_SALARY * 0.9: # If opponents bid very high (over 135)
            base_bid = DAILY_SALARY * 0.7 # Try to save money (105)
        else:
            base_bid = DAILY_SALARY * 0.75 # (112.5)

    # If there's a strong previous bid, try to beat it
    if max_prev_bid > 0 and base_bid <= max_prev_bid:
        base_bid = max_prev_bid + 1.0

    # Consider opponents' budgets. If all remaining opponents have very low budget, no need to overbid.
    low_budget_opponents = [o for o in alive_opponents if o['budget'] < DAILY_SALARY * 0.5]

    if len(low_budget_opponents) == len(alive_opponents) and len(alive_opponents) > 0:
        # All remaining opponents seem to have low budget
        if max_prev_bid > 0:
            base_bid = min(base_bid, max_prev_bid + 1.0, DAILY_SALARY * 0.6) # Cap at 90
        else:
            base_bid = min(base_bid, DAILY_SALARY * 0.4) # Cap at 60

    # Ensure bid does not exceed my budget
    final_bid = min(my_status['budget'], base_bid)

    # Ensure bid is at least 1 to participate
    return max(1.0, final_bid)

